import * as vscode from 'vscode';

import { QueuedNdjsonFileTransport } from './transports/file';

import type { LogEntry } from './types';

const entry = (over: Partial<LogEntry> = {}): LogEntry => ({
  timestamp: new Date().toISOString(),
  level: 'INFO',
  module: 'test',
  message: 'evt',
  ...over,
});

describe('QueuedNdjsonFileTransport (mock vscode)', () => {
  beforeEach(() => {
    hoisted.files.clear();
    hoisted.logFileEnabled = true;
    hoisted.logFileMaxBytes = 10_000_000;
  });

  it('no persiste cuando logFileEnabled es falso', async () => {
    hoisted.logFileEnabled = false;
    const logsDir = vscode.Uri.file('/logs/off');
    const t = new QueuedNdjsonFileTransport(
      logsDir,
      () => hoisted.logFileEnabled,
      () => hoisted.logFileMaxBytes,
    );
    await t.write(entry());
    await t.dispose();
    expect(hoisted.files.size).toBe(0);
  });

  it('escribe NDJSON y Markdown tras dispose', async () => {
    const logsDir = vscode.Uri.file('/logs/ok');
    const ndPath = vscode.Uri.joinPath(logsDir, 'events.ndjson').fsPath;
    const mdPath = vscode.Uri.joinPath(logsDir, 'session.md').fsPath;
    const t = new QueuedNdjsonFileTransport(
      logsDir,
      () => hoisted.logFileEnabled,
      () => hoisted.logFileMaxBytes,
    );
    await t.write(entry({ message: 'one' }));
    await t.dispose();
    const nd = hoisted.files.get(ndPath);
    expect(nd).toBeDefined();
    const text = Buffer.from(nd!).toString('utf-8');
    expect(text).toContain('"message":"one"');
    const md = hoisted.files.get(mdPath);
    expect(md).toBeDefined();
    expect(Buffer.from(md!).toString('utf-8')).toContain('one');
  });
});

import { readdirSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
/**
 * @file Tests de uso del output channel de logging.
 */import { describe, expect, it } from 'vitest';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '../../..');

/**
 * Recursively collects source file paths under a directory.
 * @param {string} directory The starting directory to scan for source files.
 * @returns {string[]} A list of matching source file paths.
 */
function collectSourceFiles(directory: string): string[] {
  const files: string[] = [];

  for (const dirent of readdirSync(directory, { withFileTypes: true })) {
    const path = join(directory, dirent.name);

    if (dirent.isDirectory()) {
      if (dirent.name === 'node_modules') {
        continue;
      }
      files.push(...collectSourceFiles(path));
    } else if (dirent.isFile() && /\.[jt]sx?$/.test(dirent.name)) {
      files.push(path);
    }
  }

  return files;
}

describe('GhostPrompt log output channel usage', () => {
  it('only creates the canonical GhostPrompt log output channel through the log manager', () => {
    const sourceFiles = collectSourceFiles(join(repoRoot, 'src'));
    const bannedPatterns = [
      /vscode\.window\.createOutputChannel\(\s*GHOSTPROMPT_LOG_CHANNEL_NAME\s*\)/,
      /vscode\.window\.createOutputChannel\(\s*['\"]GhostPrompt Log['\"]\s*\)/,
      /createOutputChannel\(\s*GHOSTPROMPT_LOG_CHANNEL_NAME\s*\)/,
      /createOutputChannel\(\s*['\"]GhostPrompt Log['\"]\s*\)/,
    ];

    const violations = sourceFiles.flatMap((filePath) => {
      const normalized = filePath.replace(/\\/g, '/');
      if (normalized.endsWith('/src/system/log/transports/outputChannel.ts')) {
        return [];
      }

      const content = readFileSync(filePath, 'utf8');
      return bannedPatterns.some((pattern) => pattern.test(content)) ? [filePath] : [];
    });

    expect(violations).toEqual([]);
  });
});

/**
 * @file Transporte: NDJSON + Markdown bajo `globalStorageUri/ghostPrompt/logs/v1/` con cola asíncrona.
 */
import { promisify } from 'node:util';
import { gzip } from 'node:zlib';

import * as vscode from 'vscode';

import type { LogEntry } from '../types';

const gzipAsync = promisify(gzip);

const EVENTS_FILE = 'events.ndjson';
const SESSION_FILE = 'session.md';

const DEFAULT_MAX_QUEUE = 2000;
const FLUSH_BATCH = 100;

/**
 * Encola entradas y vacía a disco sin bloquear al caller (micro-lotes).
 * Aplica rotación gzip del NDJSON cuando supera el tamaño máximo configurado.
 */
export class QueuedNdjsonFileTransport {
  /** @readonly */
  readonly id = 'ghostPromptFileNdjson';

  private readonly queue: LogEntry[] = [];
  private flushScheduled = false;
  private flushing = false;
  private droppedDebug = 0;
  private warnedBackpressure = false;
  private writeErrors = 0;

  /**
   * Configura el directorio de logs y los lectores perezosos de ajustes.
   * @param {vscode.Uri} logsDir Directorio `.../ghostPrompt/logs/v1`.
   * @param {() => boolean} isFileLogEnabled Lectura perezosa de `ghostPrompt.logFileEnabled`.
   * @param {() => number} getMaxBytes Lectura perezosa de `ghostPrompt.logFileMaxBytes`.
   * @param {number} [maxQueue] Tamaño máximo de cola antes de descartar `DEBUG`.
   */
  constructor(
    private readonly logsDir: vscode.Uri,
    private readonly isFileLogEnabled: () => boolean,
    private readonly getMaxBytes: () => number,
    private readonly maxQueue: number = DEFAULT_MAX_QUEUE,
  ) {}

  /**
   * Expone el número acumulado de fallos de escritura en disco.
   * @returns {number} Contador de errores de escritura (visible para tests y diagnóstico).
   */
  getWriteErrorCount(): number {
    return this.writeErrors;
  }

  /**
   * Encola una entrada para volcado asíncrono a NDJSON y Markdown.
   * @param {LogEntry} entry Entrada a encolar.
   * @returns {Promise<void>} Promesa que resuelve tras encolar (no espera al vaciado en disco).
   */
  async write(entry: LogEntry): Promise<void> {
    if (!this.isFileLogEnabled()) {
      return;
    }
    if (this.queue.length >= this.maxQueue) {
      const idx = this.queue.findIndex((e) => e.level === 'DEBUG');
      if (idx >= 0) {
        this.queue.splice(idx, 1);
        this.droppedDebug += 1;
      } else {
        this.queue.shift();
      }
      if (!this.warnedBackpressure && this.droppedDebug > 10) {
        this.warnedBackpressure = true;
        console.warn(
          `[GhostPrompt] Log file queue backpressure: dropped DEBUG entries (count=${this.droppedDebug}).`,
        );
      }
    }
    this.queue.push(entry);
    this.scheduleFlush();
  }

  /**
   * Vacía la cola pendiente y deja de aceptar trabajo nuevo.
   * @returns {Promise<void>} Promesa que termina cuando la cola está vacía.
   */
  async dispose(): Promise<void> {
    while (this.queue.length > 0 || this.flushing) {
      await this.flushOnce();
    }
  }

  private scheduleFlush(): void {
    if (this.flushScheduled) {
      return;
    }
    this.flushScheduled = true;
    queueMicrotask(() => {
      this.flushScheduled = false;
      void this.flushOnce();
    });
  }

  private async flushOnce(): Promise<void> {
    if (this.flushing || this.queue.length === 0) {
      return;
    }
    if (!this.isFileLogEnabled()) {
      this.queue.length = 0;
      return;
    }
    this.flushing = true;
    try {
      const batch: LogEntry[] = [];
      while (batch.length < FLUSH_BATCH && this.queue.length > 0) {
        const e = this.queue.shift();
        if (e) {
          batch.push(e);
        }
      }
      if (batch.length === 0) {
        return;
      }
      await vscode.workspace.fs.createDirectory(this.logsDir);
      await this.appendNdjsonBatch(batch);
      await this.appendMarkdownBatch(batch);
      if (this.queue.length > 0) {
        this.scheduleFlush();
      }
    } catch (e) {
      this.writeErrors += 1;
      console.error('[GhostPrompt] File log transport write failed', e);
    } finally {
      this.flushing = false;
    }
  }

  private async appendNdjsonBatch(batch: LogEntry[]): Promise<void> {
    const ndjsonUri = vscode.Uri.joinPath(this.logsDir, EVENTS_FILE);
    await this.maybeRotate(ndjsonUri);
    const lines = batch.map((b) => `${JSON.stringify(b)}\n`).join('');
    let existing = Buffer.alloc(0);
    try {
      existing = Buffer.from(await vscode.workspace.fs.readFile(ndjsonUri));
    } catch {
      // archivo nuevo
    }
    const next = Buffer.concat([existing, Buffer.from(lines, 'utf-8')]);
    await vscode.workspace.fs.writeFile(ndjsonUri, next);
  }

  private async maybeRotate(ndjsonUri: vscode.Uri): Promise<void> {
    let size = 0;
    try {
      const st = await vscode.workspace.fs.stat(ndjsonUri);
      size = st.size;
    } catch {
      size = 0;
    }
    const maxBytes = this.getMaxBytes();
    if (size < maxBytes) {
      return;
    }
    try {
      const raw = await vscode.workspace.fs.readFile(ndjsonUri);
      const stamp = new Date().toISOString().replace(/[:]/g, '-');
      const gzUri = vscode.Uri.joinPath(this.logsDir, `events.${stamp}.ndjson.gz`);
      const gzipped = await gzipAsync(raw);
      await vscode.workspace.fs.writeFile(gzUri, gzipped);
      await vscode.workspace.fs.delete(ndjsonUri, { useTrash: false });
    } catch (e) {
      this.writeErrors += 1;
      console.error('[GhostPrompt] events.ndjson rotation failed', e);
    }
  }

  private async appendMarkdownBatch(batch: LogEntry[]): Promise<void> {
    const mdUri = vscode.Uri.joinPath(this.logsDir, SESSION_FILE);
    const parts: string[] = [];
    for (const e of batch) {
      const data =
        e.data && Object.keys(e.data).length > 0
          ? `\n${Object.entries(e.data)
              .map(([k, v]) => `${k}=${typeof v === 'string' ? v : JSON.stringify(v)}`)
              .join('\n')}\n`
          : '\n';
      parts.push(`### ${e.level} ${e.module} ${e.message}\n${data}\n`);
    }
    const block = parts.join('');
    let existing = '';
    try {
      existing = Buffer.from(await vscode.workspace.fs.readFile(mdUri)).toString('utf-8');
    } catch {
      existing = '# GhostPrompt Log\n\n';
    }
    const next = existing + block;
    await vscode.workspace.fs.writeFile(mdUri, Buffer.from(next, 'utf-8'));
  }
}

/**
 * @file Transporte: canal de salida VS Code **GhostPrompt Log**.
 */
import * as vscode from 'vscode';

import type { LogEntry } from '../types';

/** Nombre visible del canal (histórico: *GhostPrompt Suggestions*). */
export const GHOSTPROMPT_LOG_CHANNEL_NAME = 'GhostPrompt Log';

/**
 * Formatea marca de tiempo ISO a `HH:mm:ss.SSS` local.
 * @param {string} iso Fecha ISO 8601.
 * @returns {string} Fragmento horario legible.
 */
export function formatLocalTime(iso: string): string {
  const d = new Date(iso);
  const hh = d.getHours().toString().padStart(2, '0');
  const mm = d.getMinutes().toString().padStart(2, '0');
  const ss = d.getSeconds().toString().padStart(2, '0');
  const ms = d.getMilliseconds().toString().padStart(3, '0');
  return `${hh}:${mm}:${ss}.${ms}`;
}

/**
 * Serializa `data` para anexarlo a la línea de log; ante fallo devuelve un literal seguro.
 * @param {Record<string, unknown>} data Metadatos del evento.
 * @returns {string} JSON o cadena de marcador de posición.
 */
function safeJson(data: Record<string, unknown>): string {
  try {
    return JSON.stringify(data);
  } catch {
    return '"[unserializable]"';
  }
}

/**
 * Escribe líneas de texto en un {@link vscode.OutputChannel} (append síncrono, bajo coste).
 * Crea el canal bajo demanda la primera vez que se escribe.
 */
export class OutputChannelLogTransport {
  /** @readonly */
  readonly id = 'ghostPromptOutputChannel';

  private channel: vscode.OutputChannel | undefined;

  /**
   * Crea el canal si aún no existe (idempotente).
   * @returns {vscode.OutputChannel} Canal listo para `appendLine`.
   */
  ensureChannel(): vscode.OutputChannel {
    if (!this.channel) {
      this.channel = vscode.window.createOutputChannel(GHOSTPROMPT_LOG_CHANNEL_NAME);
    }
    return this.channel;
  }

  /**
   * Serializa una entrada a una línea humana.
   * @param {LogEntry} entry Entrada estructurada.
   * @returns {string} Línea para `appendLine`.
   */
  formatLine(entry: LogEntry): string {
    const t = formatLocalTime(entry.timestamp);
    const data =
      entry.data && Object.keys(entry.data).length > 0 ? ` | ${safeJson(entry.data)}` : '';
    const err = entry.error
      ? ` | ${entry.error.name}: ${entry.error.message}${
          entry.error.stack ? `\n${entry.error.stack}` : ''
        }`
      : '';
    const crumbs =
      entry.breadcrumbs && entry.breadcrumbs.length > 0
        ? ` | breadcrumbs=${entry.breadcrumbs.length}`
        : '';
    return `[${t}] [${entry.level}] [${entry.module}] ${entry.message}${data}${crumbs}${err}`;
  }

  /**
   * Añade una línea legible al canal GhostPrompt Log.
   * @param {LogEntry} entry Entrada a volcar al canal.
   * @returns {Promise<void>} Promesa resuelta tras `appendLine`.
   */
  async write(entry: LogEntry): Promise<void> {
    this.ensureChannel().appendLine(this.formatLine(entry));
  }

  /**
   * Libera el canal de salida si se había creado.
   * @returns {Promise<void>} Promesa resuelta tras `dispose` del canal si existía.
   */
  async dispose(): Promise<void> {
    this.channel?.dispose();
    this.channel = undefined;
  }
}

